// 診断タグ → 文学タイプの対応
function detectLitType(tags) {
  return [...LIT_TYPES]
    .map(t => ({ ...t, score: t.tags.filter(tag => tags.includes(tag)).length }))
    .sort((a,b) => b.score - a.score)[0];
}

const TYPES_CFG = {
  赤:       { label:"赤ワイン",       color:"#8B1A2A", bg:"#FEF8F8" },
  白:       { label:"白ワイン",       color:"#8A7820", bg:"#FDFDF0" },
  オレンジ: { label:"オレンジワイン", color:"#C05010", bg:"#FEF8F0" },
  泡:       { label:"スパークリング", color:"#5A8A30", bg:"#F8FDF0" },
  ロゼ:     { label:"ロゼワイン",     color:"#C02858", bg:"#FEF4F8" },
  デザート: { label:"デザートワイン", color:"#A07818", bg:"#FEF8E8" },
};

function detectType(tags) {
  return [...TYPE_MAP].map(t=>({...t, score:t.tags.filter(tag=>tags.includes(tag)).length})).sort((a,b)=>b.score-a.score)[0];
}
function scoreWine(selectedTags, wine) {
  return wine.tags.filter(t=>selectedTags.includes(t)).length;
}

