// GLASS IMAGE COMPONENT
// ============================================================
function GlassImg({ type, size=120, hover=false }) {
  const cfg = TYPES_CFG[type]||TYPES_CFG["赤"];
  return (
    <div style={{width:size,height:size,transition:"transform 0.3s, filter 0.3s",transform:hover?"translateY(-6px) scale(1.05)":"none",filter:hover?`drop-shadow(0 8px 20px ${cfg.color}44)`:"none"}}>
      <img src={IMG[type]} alt={cfg.label} style={{width:"100%",height:"100%",objectFit:"contain",filter:GLASS_FILTER[type]||"none",transition:"filter 0.3s"}}/>
    </div>
  );
}

