// ============================================================
// PRODUCER PROFILE TRIGGER (inline in WineCard)
// ============================================================
function ProducerProfileTrigger({ producerName, wine }) {
  const [show, setShow] = useState(false);
  const p = PRODUCERS[producerName];
  if(!p) return null;
  return (
    <>
      <button onClick={()=>setShow(true)}
        style={{width:"100%",padding:"8px 12px",background:"#FAF7F2",border:"1px solid #D8C8A8",borderRadius:6,fontSize:11,color:"#6a5040",cursor:"pointer",marginTop:4,fontFamily:"Georgia,serif",display:"flex",alignItems:"center",gap:6,justifyContent:"center",transition:"all 0.15s"}}
        onMouseEnter={e=>{e.currentTarget.style.background="#F0E8D8";}}
        onMouseLeave={e=>{e.currentTarget.style.background="#FAF7F2";}}>
        {p.emoji} 造り手のストーリーを読む →
      </button>
      {show && <ProducerProfileModal producerName={producerName} wine={wine} onClose={()=>setShow(false)}/>}
    </>
  );
}

// ============================================================
// PRODUCER PROFILE MODAL
// ============================================================
function ProducerProfileModal({ producerName, wine, onClose }) {
  const p = PRODUCERS[producerName];
  if(!p) return null;
  return (
    <div onClick={onClose} style={{position:"fixed",inset:0,background:"rgba(8,6,4,0.82)",display:"flex",alignItems:"flex-end",justifyContent:"center",zIndex:300,backdropFilter:"blur(10px)"}}>
      <div onClick={e=>e.stopPropagation()} style={{background:"#FDFCFA",borderRadius:"20px 20px 0 0",padding:"0 0 48px",width:"100%",maxWidth:520,maxHeight:"88vh",overflowY:"auto",animation:"up 0.3s ease"}}>
        <div style={{padding:"12px 0 0",display:"flex",justifyContent:"center"}}>
          <div style={{width:36,height:4,background:"#DDD5C8",borderRadius:2}}/>
        </div>
        <div style={{padding:"16px 20px 18px",borderBottom:"1px solid #EDE6DC",background:"linear-gradient(135deg,#FAF7F2,#fff)"}}>
          <div style={{fontSize:9,color:"#a09080",letterSpacing:"0.3em",textTransform:"uppercase",marginBottom:5}}>造り手の物語</div>
          <div style={{fontSize:21,color:"#1a1410",fontFamily:"Georgia,serif",marginBottom:2,display:"flex",alignItems:"center",gap:8}}>
            {p.emoji} {producerName}
            <FavoriteButton type="producer" id={producerName.replace(/\s/g,"_")} name={producerName} extra={{region:p.region,domaine:p.domaine}}/>
          </div>
          <div style={{fontSize:11,color:"#8a7a68"}}>{p.domaine} · {p.region}</div>
        </div>
        <div style={{padding:"18px 20px"}}>
          <div style={{display:"inline-block",background:"#F5F0E8",border:"1px solid #D8C8A8",borderRadius:6,padding:"4px 12px",marginBottom:14}}>
            <span style={{fontSize:10,color:"#6a5040"}}>{p.mbti}</span>
          </div>
          <p style={{fontSize:13.5,color:"#3a2a18",lineHeight:1.85,margin:"0 0 18px",fontFamily:"Georgia,serif"}}>{p.story}</p>
          {p.philosophy && (
            <div style={{marginBottom:18}}>
              <div style={{fontSize:9,color:"#a09080",letterSpacing:"0.2em",textTransform:"uppercase",marginBottom:8}}>醸造の哲学</div>
              <div style={{display:"flex",gap:6,flexWrap:"wrap"}}>
                {p.philosophy.map(ph=><span key={ph} style={{fontSize:10,padding:"3px 10px",background:"#F0EDE5",border:"1px solid #D8D0C8",borderRadius:20,color:"#5a4a38"}}>{ph}</span>)}
              </div>
            </div>
          )}
          {wine && (
            <>
              <div style={{background:"#FAF9F7",border:"1px solid #EDE6DC",borderRadius:8,padding:"12px 14px",marginBottom:14}}>
                <div style={{fontSize:9,color:"#a09080",letterSpacing:"0.15em",textTransform:"uppercase",marginBottom:4}}>代表ワイン</div>
                <div style={{fontSize:14,color:"#1a1410",fontFamily:"Georgia,serif",marginBottom:3}}>{wine.name}</div>
                <div style={{display:"flex",justifyContent:"space-between",alignItems:"center"}}>
                  <div style={{fontSize:11,color:"#8a7a68"}}>{wine.region}</div>
                  <div style={{fontSize:12,color:"#8B1A2A",fontWeight:600}}>{wine.price}</div>
                </div>
              </div>
              <a href={wine.buyUrl} target="_blank" rel="noopener noreferrer"
                style={{display:"flex",alignItems:"center",justifyContent:"center",gap:8,padding:"13px",background:"#1a1410",color:"#f0e8d8",borderRadius:8,textDecoration:"none",fontSize:13,fontFamily:"Georgia,serif",fontWeight:600,marginBottom:10}}>
                🛒 このワインを探す
              </a>
            </>
          )}
          <button onClick={onClose} style={{width:"100%",padding:"11px",background:"transparent",border:"1px solid #EDE6DC",color:"#8a7a68",borderRadius:8,fontSize:12,cursor:"pointer",fontFamily:"Georgia,serif"}}>閉じる</button>
        </div>
      </div>
    </div>
  );
}

export default function App() {
  const [screen, setScreen] = useState("home");
  return (
    <div style={{minHeight:"100vh",background:"#FDFCFA",color:"#1a1410",fontFamily:"Georgia,serif"}}>
      <style>{`
        @keyframes fadeUp { from{opacity:0;transform:translateY(10px)} to{opacity:1;transform:translateY(0)} }
        @keyframes pulse  { 0%,100%{opacity:0.4;transform:scale(0.95)} 50%{opacity:1;transform:scale(1.05)} }
        @keyframes up     { from{transform:translateY(100%)} to{transform:translateY(0)} }
        @keyframes show   { from{opacity:0;transform:translateY(8px)} to{opacity:1;transform:translateY(0)} }
      `}</style>

      {/* HEADER */}
      <div style={{borderBottom:"1px solid #EDE6DC",padding:"18px 24px",background:"#FDFCFA",position:"sticky",top:0,zIndex:10}}>
        <div style={{maxWidth:640,margin:"0 auto",display:"flex",alignItems:"center",justifyContent:"space-between"}}>
          <button onClick={()=>setScreen("home")} style={{background:"none",border:"none",cursor:"pointer",padding:0,textAlign:"left"}}>
            <div style={{fontSize:9,letterSpacing:"0.4em",color:"#B0A090",textTransform:"uppercase"}}>tsugi</div>
            <div style={{fontSize:12,color:"#8B1A2A",fontStyle:"italic"}}>次の一杯へ</div>
          </button>
          {screen!=="home"&&<button onClick={()=>setScreen("home")} style={{fontSize:11,color:"#B0A090",background:"none",border:"none",cursor:"pointer"}}>← ホーム</button>}
        </div>
      </div>

      <div style={{maxWidth:640,margin:"0 auto",padding:"0 20px 64px"}}>
        {screen==="home"      && <HomeScreen onSelect={setScreen}/>}
        {screen==="finder"    && <FinderScreen/>}
        {screen==="diagnosis" && <DiagnosisScreen mode="self"/>}
        {screen==="gift"      && <SenderScreen onHome={()=>setScreen("home")}/>}
        {screen==="reverse"   && <ReverseScreen onHome={()=>setScreen("home")}/>}
        {screen==="mypage"    && <MyPageScreen onBack={()=>setScreen("home")}/>}
        {screen==="literature" && <LiteratureDiagnosisScreen onHome={()=>setScreen("home")}/>}
        {screen==="recipient" && <RecipientScreen onHome={()=>setScreen("home")}/>}
        {screen.startsWith("taste:") && <TasteSearchScreen initialTaste={screen.replace("taste:","")} onBack={()=>setScreen("home")}/>}
        {screen.startsWith("winetype:") && <TasteSearchScreen wineTypeFilter={screen.replace("winetype:","")} onBack={()=>setScreen("home")}/>}
      </div>
    </div>
  );
}

