function FinderScreen() {
  const [sel, setSel]     = useState([]);
  const [step, setStep]   = useState("select");
  const [results, setRes] = useState(null);
  const [loading, setLoad]= useState(false);
  const [fb, setFb]       = useState({});

  const toggle = item => setSel(p=>p.find(s=>s.id===item.id)?p.filter(s=>s.id!==item.id):[...p,item]);

  const find = async () => {
    if(!sel.length) return;
    setLoad(true); setStep("results");
    const allTags = sel.flatMap(s=>s.tags);
    const scored = WINE_DB.map(w=>({...w,score:scoreWine(allTags,w)})).filter(w=>w.score>0).sort((a,b)=>b.score-a.score).slice(0,4);
    try {
      const res = await fetch("https://api.anthropic.com/v1/messages",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({model:"claude-sonnet-4-20250514",max_tokens:800,messages:[{role:"user",content:`ナチュラルワインのソムリエとして2〜3文の日本語コメントを。好みのお酒: ${sel.map(s=>s.name).join("、")}。おすすめ1位: ${scored[0]?.name}。専門用語なしで親しみやすく。`}]})});
      const data = await res.json();
      setRes({wines:scored, comment:data.content?.[0]?.text||""});
    } catch { setRes({wines:scored,comment:""}); }
    setLoad(false);
  };

  if(step==="results"&&loading) return <LoadingScreen emoji="🍷" text="テイストを照合中..."/>;

  if(step==="results"&&results) return (
    <div style={{paddingTop:24,animation:"fadeUp 0.4s ease"}}>
      {results.comment&&<div style={{background:"#FEF8F8",border:"1px solid #EDE6DC",borderLeft:"3px solid #8B1A2A",borderRadius:6,padding:"14px 16px",marginBottom:20,fontSize:13,lineHeight:1.8,color:"#5a3a3a",fontStyle:"italic"}}>🍷 {results.comment}</div>}
      {results.wines.map((wine,i)=><WineCard key={wine.id} wine={wine} rank={i+1} fb={fb[wine.id]} onFb={(id,v)=>setFb(p=>({...p,[id]:v}))}/>)}
      <RakutenLiveSearch tags={sel.flatMap(s=>s.tags).slice(0,3)}/>
      <button onClick={()=>{setSel([]);setStep("select");setRes(null);}} style={{width:"100%",padding:"12px",background:"transparent",border:"1px solid #EDE6DC",color:"#8a7a68",borderRadius:6,fontSize:13,cursor:"pointer",marginTop:8}}>← 選び直す</button>
    </div>
  );

  return (
    <div style={{paddingTop:24,animation:"fadeUp 0.4s ease"}}>
      <div style={{fontSize:13,color:"#8a7a68",marginBottom:20}}>普段よく飲むものを選んでください（複数OK）</div>
      <Section title="🍺 ビール">{BEER_OPTIONS.map(item=><Chip key={item.id} item={item} selected={!!sel.find(s=>s.id===item.id)} onToggle={toggle} accent="#8B1A2A"/>)}</Section>
      <Section title="🍶 日本酒">{SAKE_OPTIONS.map(item=><Chip key={item.id} item={item} selected={!!sel.find(s=>s.id===item.id)} onToggle={toggle} accent="#8B1A2A"/>)}</Section>
      <Section title="🥃 ハイボール・ウイスキー・焼酎">{WHISKY_OPTIONS.map(item=><Chip key={item.id} item={item} selected={!!sel.find(s=>s.id===item.id)} onToggle={toggle} accent="#8B1A2A"/>)}</Section>
      <Section title="🍋 酎ハイ・サワー・梅酒">{CHUHAI_OPTIONS.map(item=><Chip key={item.id} item={item} selected={!!sel.find(s=>s.id===item.id)} onToggle={toggle} accent="#8B1A2A"/>)}</Section>
      <Section title="🍷 市販ワイン（飲み口で）">{WINE_MARKET_OPTIONS.map(item=><Chip key={item.id} item={item} selected={!!sel.find(s=>s.id===item.id)} onToggle={toggle} accent="#8B1A2A"/>)}</Section>
      <Section title="🙅 飲まない">{[{id:"nothing",name:"お酒をあまり飲まない",tags:["light","clean","fresh"]}].map(item=><Chip key={item.id} item={item} selected={!!sel.find(s=>s.id===item.id)} onToggle={toggle} accent="#8B1A2A"/>)}</Section>
      {sel.length>0&&<div style={{fontSize:11,color:"#8a7a68",marginBottom:12}}>選択中: {sel.map(s=>s.name).join("、")}</div>}
      <button onClick={find} disabled={!sel.length} style={{width:"100%",padding:"14px",background:sel.length?"#8B1A2A":"#EDE6DC",color:sel.length?"#fff":"#a09080",border:"none",borderRadius:6,fontSize:14,cursor:sel.length?"pointer":"not-allowed",letterSpacing:"0.06em",transition:"all 0.2s"}}>
        ナチュラルワインを探す →
      </button>
    </div>
  );
}

